    category: "Java Basics",
    question: "What are operators in Java?",
    idealAnswer: "**Operators**: Special symbols performing operations on operands.\n\n**1. Arithmetic Operators**:\n```java\npublic class ArithmeticOps {\n    public static void main(String[] args) {\n        int a = 10, b = 3;\n        \n        System.out.println(\"Addition: \" + (a + b));      // 13\n        System.out.println(\"Subtraction: \" + (a - b));   // 7\n        System.out.println(\"Multiplication: \" + (a * b)); // 30\n        System.out.println(\"Division: \" + (a / b));      // 3 (integer division)\n        System.out.println(\"Modulus: \" + (a % b));       // 1 (remainder)\n        \n        // Floating point division\n        System.out.println(\"Float division: \" + (a / (double)b)); // 3.333...\n    }\n}\n```\n\n**2. Relational Operators**:\n```java\npublic class RelationalOps {\n    public static void main(String[] args) {\n        int x = 5, y = 10;\n        \n        System.out.println(\"x == y: \" + (x == y));  // false\n        System.out.println(\"x != y: \" + (x != y));  // true\n        System.out.println(\"x > y: \" + (x > y));    // false\n        System.out.println(\"x < y: \" + (x < y));    // true\n        System.out.println(\"x >= y: \" + (x >= y));  // false\n        System.out.println(\"x <= y: \" + (x <= y));  // true\n    }\n}\n```\n\n**3. Logical Operators**:\n```java\npublic class LogicalOps {\n    public static void main(String[] args) {\n        boolean a = true, b = false;\n        \n        System.out.println(\"a && b: \" + (a && b));  // false (AND)\n        System.out.println(\"a || b: \" + (a || b));  // true  (OR)\n        System.out.println(\"!a: \" + (!a));          // false (NOT)\n        \n        // Short-circuit evaluation\n        int x = 5;\n        if (x > 0 && (x = 10) > 5) {\n            System.out.println(\"x after AND: \" + x); // x becomes 10\n        }\n        \n        int y = 5;\n        if (y < 0 || (y = 10) > 5) {\n            System.out.println(\"y after OR: \" + y);  // y becomes 10\n        }\n    }\n}\n```\n\n**4. Assignment Operators**:\n```java\npublic class AssignmentOps {\n    public static void main(String[] args) {\n        int x = 10;\n        \n        x += 5;  // x = x + 5;  // 15\n        x -= 3;  // x = x - 3;  // 12\n        x *= 2;  // x = x * 2;  // 24\n        x /= 4;  // x = x / 4;  // 6\n        x %= 4;  // x = x % 4;  // 2\n        \n        System.out.println(\"Final x: \" + x);  // 2\n    }\n}\n```\n\n**5. Unary Operators**:\n```java\npublic class UnaryOps {\n    public static void main(String[] args) {\n        int x = 5;\n        \n        // Increment/Decrement\n        System.out.println(\"x++: \" + (x++));  // 5 (post-increment)\n        System.out.println(\"x: \" + x);        // 6\n        System.out.println(\"++x: \" + (++x));  // 7 (pre-increment)\n        \n        // Sign operators\n        System.out.println(\"+x: \" + (+x));    // 7\n        System.out.println(\"-x: \" + (-x));    // -7\n        \n        // Logical NOT\n        boolean flag = true;\n        System.out.println(\"!flag: \" + (!flag)); // false\n    }\n}\n```\n\n**6. Bitwise Operators**:\n```java\npublic class BitwiseOps {\n    public static void main(String[] args) {\n        int a = 5;  // 0101\n        int b = 3;  // 0011\n        \n        System.out.println(\"a & b: \" + (a & b));   // 1 (0001) - AND\n        System.out.println(\"a | b: \" + (a | b));   // 7 (0111) - OR\n        System.out.println(\"a ^ b: \" + (a ^ b));   // 6 (0110) - XOR\n        System.out.println(\"~a: \" + (~a));         // -6 (complement)\n        \n        // Shift operators\n        System.out.println(\"a << 1: \" + (a << 1)); // 10 (1010) - left shift\n        System.out.println(\"a >> 1: \" + (a >> 1)); // 2 (0010) - right shift\n        System.out.println(\"a >>> 1: \" + (a >>> 1)); // 2 - unsigned right shift\n    }\n}\n```\n\n**7. Ternary Operator**:\n```java\npublic class TernaryOp {\n    public static void main(String[] args) {\n        int age = 18;\n        \n        // Condition ? value_if_true : value_if_false\n        String message = (age >= 18) ? \"Adult\" : \"Minor\";\n        System.out.println(message);  // Adult\n        \n        // Nested ternary\n        int score = 85;\n        char grade = (score >= 90) ? 'A' : \n                     (score >= 80) ? 'B' : \n                     (score >= 70) ? 'C' : 'F';\n        System.out.println(\"Grade: \" + grade);  // B\n    }\n}\n```\n\n**8. Operator Precedence**:\n```java\npublic class Precedence {\n    public static void main(String[] args) {\n        int result = 2 + 3 * 4;      // 14 (multiplication first)\n        int result2 = (2 + 3) * 4;    // 20 (parentheses first)\n        \n        boolean condition = 5 > 3 && 2 < 4;  // true\n        boolean condition2 = 5 > (3 && 2) < 4; // Compile error!\n        \n        System.out.println(\"Result: \" + result);\n        System.out.println(\"Condition: \" + condition);\n    }\n}\n```",
