// Group questions by difficulty
const categories = {
  easy: (javaQuestions || []).filter(q => {
    if (!q) return false;
    return q.difficulty === 'Easy' || (!q.difficulty && q.id <= 25);
  }),
  medium: (javaQuestions || []).filter(q => {
    if (!q) return false;
    return q.difficulty === 'Medium';
  }),
  hard: (javaQuestions || []).filter(q => {
    if (!q) return false;
    return q.difficulty === 'Hard';
  })
};

